@Entity
public class Order {
    @Id @GeneratedValue
    private Long id;

    // Explicitly set to LAZY to avoid unnecessary JOINs
    @ManyToOne(fetch = FetchType.LAZY)
    private Customer customer;

    // Collections default to LAZY, but explicit declaration is best practice
    @OneToMany(mappedBy = "order", fetch = FetchType.LAZY)
    private List<OrderItem> items;
}
